    @get:JsonProperty("minChargePower_L2")
    val minChargePowerL2: BigDecimal? = null,
    /**
     * Minimum charge power on phase L3 in W, defined by max(EV, EVSE).
     * Relates to:
     * *ISO 15118-20*: BPT_AC/DC_CPDReqEnergyTransferModeType: EVMinimumChargePower_L3
     */
    @param:JsonProperty("minChargePower_L3")
    @get:JsonProperty("minChargePower_L3")
