    /**
     * Maximum discharge power on phase L2 in W, defined by min(EV, EVSE).  Value &gt;= 0.
     * Relates to:
     * *ISO 15118-20*: BPT_AC/DC_CPDReqEnergyTransferModeType: EVMaximumDischargePowe_L2
     */
